/* Illustrated vocabulary picker inside the shared OIS editor/save/import workflow. */
function launchSupermarketLesson(lesson){const cfg=supermarketConfig(lesson.settings.supermarket);dirty=false;location.href='./supermarket/index.html#lesson='+encodeURIComponent(JSON.stringify({id:lesson.id,title:lesson.title,...cfg}));}
(()=>{
 const panel=document.createElement('section');panel.className='panel supermarket-editor';panel.hidden=true;$('.editor-main').append(panel);let selection=new Set(),letters=new Set(),page=0;
 const filtered=()=>{const query=$('#shop-search').value.trim().toLowerCase(),category=$('#shop-category').value,initial=$('#shop-letter').value,length=$('#shop-length').value;return SHOP_WORD_LIBRARY.filter(x=>(!query||x.name.includes(query))&&(!category||x.category===category)&&(!initial||x.letter===initial)&&(!length||(length==='short'?/^[a-z]{2,3}$/.test(x.name):length==='medium'?/^[a-z]{4,5}$/.test(x.name):length==='long'?/^[a-z]{6,}$/.test(x.name):x.name.includes(' ')||x.name.includes('-')))&&(!$('#shop-selected-only').checked||selection.has(x.name)));};
 function sync(){draft.settings.supermarket={letters:[...letters].sort(),words:[...selection],stage:Number($('#shop-stage').value)};draft.items=[...selection].map(word=>({prompt:word,answer:word,options:[],hint:'',explanation:''}));dirty=true;$('#shop-selection-count').textContent=selection.size+' words selected';}
 function render(){const list=filtered();page=Math.min(page,Math.max(0,Math.ceil(list.length/48)-1));$('#shop-results').textContent=list.length+' matching words · page '+(page+1)+' of '+Math.max(1,Math.ceil(list.length/48));$('#shop-word-grid').innerHTML=list.slice(page*48,page*48+48).map(x=>`<button type="button" class="shop-word ${selection.has(x.name)?'selected':''}" data-shop-word="${esc(x.name)}" aria-pressed="${selection.has(x.name)}">${shopWordArt(x)}<span>${esc(x.name)}</span><small>${esc(x.category)}</small></button>`).join('');$('#shop-previous').disabled=page===0;$('#shop-next').disabled=(page+1)*48>=list.length;$('#shop-selection-count').textContent=selection.size+' words selected';}
 function openPicker(){const cfg=supermarketConfig(draft.settings.supermarket);selection=new Set(cfg.words);letters=new Set(cfg.letters);page=0;
 panel.innerHTML=`<h2>Your supermarket lesson</h2><p>Choose the letters to practise and the words to read. Every one of the 500 words has an illustration. Your choices are included when you save or download this lesson.</p><label>Start with<select id="shop-stage"><option value="0">Uppercase letters → lowercase → words</option><option value="1">Lowercase letters → words</option><option value="2">Words straight away</option></select></label><fieldset><legend>Letters for letter practice</legend><div class="shop-letter-grid">${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l=>`<label><input type="checkbox" data-shop-letter="${l}" ${letters.has(l)?'checked':''}><span>${l}</span></label>`).join('')}</div><button type="button" id="shop-all-letters" class="button secondary">All letters</button><button type="button" id="shop-clear-letters" class="button secondary">Clear letters</button></fieldset><h3>Illustrated words for word practice</h3><p>Letter practice uses illustrated examples starting with your chosen letters. Word practice uses only the vocabulary selected below. Some of the wider library suits older readers; start with the 2–3 letter filter.</p><div class="shop-filters"><label>Search<input id="shop-search" type="search" placeholder="Find apple, bus, dinosaur…"></label><label>Category<select id="shop-category"><option value="">All categories</option>${[...new Set(SHOP_WORD_LIBRARY.map(x=>x.category))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Starting letter<select id="shop-letter"><option value="">A–Z</option>${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l=>`<option>${l}</option>`).join('')}</select></label><label>Word length<select id="shop-length"><option value="">All lengths</option><option value="short">2–3 letters</option><option value="medium">4–5 letters</option><option value="long">6+ letters</option><option value="phrase">Word pairs & phrases</option></select></label></div><div class="shop-picker-actions"><button type="button" id="shop-add-matching" class="button secondary">Add matching words</button><button type="button" id="shop-remove-matching" class="button secondary">Remove matching words</button><button type="button" id="shop-starter" class="button secondary">Use starter words</button><label><input id="shop-selected-only" type="checkbox"> Show selected only</label><strong id="shop-selection-count" role="status"></strong></div><p id="shop-results" role="status"></p><div id="shop-word-grid"></div><div class="shop-pagination"><button type="button" id="shop-previous" class="button secondary">← Previous</button><button type="button" id="shop-next" class="button secondary">Next →</button></div><small>Additional SVG artwork: <a href="https://openmoji.org/" target="_blank" rel="noopener">OpenMoji</a>, CC BY-SA 4.0; original game artwork retained.</small>`;
 $('#shop-stage').value=cfg.stage;panel.onchange=e=>{if(e.target.dataset.shopLetter){if(e.target.checked)letters.add(e.target.dataset.shopLetter);else letters.delete(e.target.dataset.shopLetter);sync();}else if(e.target.id==='shop-stage')sync();else if(e.target.id!=='shop-search'){page=0;render();}};$('#shop-search').oninput=()=>{page=0;render();};$('#shop-word-grid').onclick=e=>{const b=e.target.closest('[data-shop-word]');if(!b)return;const word=b.dataset.shopWord;selection.has(word)?selection.delete(word):selection.add(word);sync();render();};
 for(const [id,add] of [['shop-add-matching',true],['shop-remove-matching',false]])$('#'+id).onclick=()=>{for(const x of filtered())add?selection.add(x.name):selection.delete(x.name);sync();render();};$('#shop-starter').onclick=()=>{selection=new Set(SIMPLE_SHOP_WORDS);sync();render();};
 $('#shop-all-letters').onclick=()=>{letters=new Set('ABCDEFGHIJKLMNOPQRSTUVWXYZ');panel.querySelectorAll('[data-shop-letter]').forEach(x=>x.checked=true);sync();};$('#shop-clear-letters').onclick=()=>{letters.clear();panel.querySelectorAll('[data-shop-letter]').forEach(x=>x.checked=false);sync();};$('#shop-previous').onclick=()=>{page--;render();};$('#shop-next').onclick=()=>{page++;render();};render();
 }
 const originalOpen=openEditor;openEditor=function(lesson){originalOpen(lesson);const custom=lesson.format==='supermarket-word-quest';panel.hidden=!custom;$('#editor').classList.toggle('editing-supermarket',custom);if(custom){$('#lesson-title').closest('.panel').hidden=false;openPicker();}};
 const originalRead=readDraft;readDraft=function(){if(draft?.format!=='supermarket-word-quest')return originalRead();return validateLesson({...draft,title:$('#lesson-title').value,topic:$('#lesson-topic').value,grade:Number($('#lesson-grade').value),subject:$('#lesson-subject').value});};
 if(draft?.format==='supermarket-word-quest')openEditor(draft);
})();
